CREATE TABLE IF NOT EXISTS gis_boundary_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES continental_jurisdictions(id) ON DELETE CASCADE, authority_name text NOT NULL, source_title text NOT NULL, source_url text NOT NULL, source_type text NOT NULL, provenance_status text NOT NULL DEFAULT 'Discovered', retrieved_at timestamptz NOT NULL DEFAULT now(), source_hash text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_boundary_datasets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES continental_jurisdictions(id) ON DELETE CASCADE, source_id uuid REFERENCES gis_boundary_sources(id) ON DELETE SET NULL, dataset_name text NOT NULL, dataset_version text, geometry_format text NOT NULL, coordinate_reference_system text, boundary_level text NOT NULL, feature_count integer NOT NULL DEFAULT 0, geometry_status text NOT NULL DEFAULT 'Pending', validation_status text NOT NULL DEFAULT 'Pending', effective_from timestamptz, effective_until timestamptz, imported_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_boundary_features (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_id uuid NOT NULL REFERENCES gis_boundary_datasets(id) ON DELETE CASCADE, area_id uuid REFERENCES jurisdiction_areas(id) ON DELETE SET NULL, parent_feature_id uuid REFERENCES gis_boundary_features(id) ON DELETE SET NULL, area_code text NOT NULL, area_name text NOT NULL, boundary_level text NOT NULL, geometry_geojson jsonb, geometry_hash text, validation_status text NOT NULL DEFAULT 'Pending', source_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_asset_location_checks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, latitude numeric(12,8) NOT NULL, longitude numeric(12,8) NOT NULL, dataset_id uuid REFERENCES gis_boundary_datasets(id) ON DELETE SET NULL, state_area_id uuid REFERENCES jurisdiction_areas(id) ON DELETE SET NULL, lga_area_id uuid REFERENCES jurisdiction_areas(id) ON DELETE SET NULL, resolution_status text NOT NULL DEFAULT 'Unresolved', confidence text NOT NULL DEFAULT 'Unknown', evidence_reference text, checked_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_sources_jurisdiction ON gis_boundary_sources(jurisdiction_id,provenance_status);
CREATE INDEX IF NOT EXISTS idx_gis_datasets_level ON gis_boundary_datasets(jurisdiction_id,boundary_level,validation_status);
CREATE INDEX IF NOT EXISTS idx_gis_features_dataset ON gis_boundary_features(dataset_id,boundary_level,area_code);
CREATE INDEX IF NOT EXISTS idx_gis_asset_checks_asset ON gis_asset_location_checks(asset_id,checked_at DESC);